import * as THREE from 'three';

const ARM_AMPLITUDE = 0.5; // max |rotation.z| of the pendulum arm
// Tolerance used when detecting integer-beat crossings, so that float
// accumulation drift (e.g. 30 steps of 1/60 s at 120 bpm) still lands a tick.
const TICK_EPS = 1e-9;

/**
 * Current beat position (phase) of the metronome in beats.
 *   beats = elapsed * bpm / 60 + phaseOffset
 * `phaseOffset` is recomputed by setBpm so the arm never jumps.
 */
function beatsOf(m) {
  return m.elapsed * (m.bpm / 60) + m.phaseOffset;
}

export class Metronome extends EventEmitter {
  constructor({ bpm = 60 } = {}) {
    super();
    if (!(bpm > 0)) throw new RangeError(`bpm must be > 0, got ${bpm}`);
    this.bpm = bpm;
    this.elapsed = 0;      // internal clock, seconds
    this.phaseOffset = 0;  // beats offset keeping phase continuous across setBpm
    this.lastBeat = 0;     // last whole beat whose tick was emitted

    // --- wedge body (triangular prism) ---
    const shape = new THREE.Shape();
    shape.moveTo(-1, 0);
    shape.lineTo(1, 0);
    shape.lineTo(0, 2);
    shape.closePath();
    const bodyGeo = new THREE.ExtrudeGeometry(shape, {
      depth: 0.5,
      bevelEnabled: false,
    });
    bodyGeo.translate(0, 0, -0.25); // center on z
    this.body = new THREE.Mesh(
      bodyGeo,
      new THREE.MeshStandardMaterial({ color: 0x8b4513 })
    );
    this.body.name = 'metronome-body';

    // --- pendulum arm group (pivot at the top vertex) ---
    this.arm = new THREE.Group();
    this.arm.name = 'metronome-arm';
    this.arm.position.set(0, 1.9, 0);

    const rod = new THREE.Mesh(
      new THREE.BoxGeometry(0.06, 1.2, 0.06),
      new THREE.MeshStandardMaterial({ color: 0xdddddd })
    );
    rod.position.y = -0.6; // extend downward from pivot
    rod.name = 'metronome-rod';

    const bob = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 16, 16),
      new THREE.MeshStandardMaterial({ color: 0xffcc00 })
    );
    bob.position.y = -0.95;
    bob.name = 'metronome-bob';

    this.arm.add(rod, bob);
    this.body.add(this.arm);

    this.arm.rotation.z = ARM_AMPLITUDE * Math.sin(Math.PI * beatsOf(this));
  }
}

/** Create a metronome asset: { body, arm } plus an EventEmitter API (m.on). */
export function createMetronome(options = {}) {
  return new Metronome(options);
}

/**
 * Advance the internal clock by dt seconds, swing the arm with
 *   rotation.z = 0.5 * sin(2π * beats / 2)
 * (one full left-right-left cycle per two beats), and emit a "tick" event
 * carrying the beat number each time the beat counter crosses an integer.
 */
export function stepMetronome(m, dt) {
  m.elapsed += dt;
  const beats = beatsOf(m);

  // Emit one tick per integer crossed since the previous step.
  const n = Math.floor(beats + TICK_EPS);
  while (m.lastBeat < n) {
    m.lastBeat += 1;
    m.emit('tick', m.lastBeat);
  }

  m.arm.rotation.z = ARM_AMPLITUDE * Math.sin(Math.PI * beats);
  return beats;
}

/**
 * Change tempo without jumping the arm: recompute the phase offset so that
 * the beat position (and hence arm rotation) is identical before and after
 * the call; only the rate of future advancement changes.
 */
export function setBpm(m, bpm) {
  if (!(bpm > 0)) throw new RangeError(`bpm must be > 0, got ${bpm}`);
  const current = beatsOf(m);           // beat position at this instant
  m.bpm = bpm;
  m.phaseOffset = current - m.elapsed * (m.bpm / 60);
  // Keep the visual state exactly in sync with the (unchanged) phase.
  m.arm.rotation.z = ARM_AMPLITUDE * Math.sin(Math.PI * beatsOf(m));
  return m;
}
