result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/metronome.test.js", "content": "import { describe, it, expect } from 'vitest';
import { createMetronome, stepMetronome, setBpm } from '../src/metronome.js';

const DT = 1 / 60;

describe('metronome asset', () => {
  it('at 120 bpm, 30 steps of dt = 1/60 lands exactly 1 tick', () => {
    const m = createMetronome({ bpm: 120 });
    const ticks = [];
    m.on('tick', (beat) => ticks.push(beat));
    for (let i = 0; i < 30; i++) stepMetronome(m, DT);
    expect(ticks).toEqual([1]);
  });

  it('over 10 simulated seconds at 120 bpm exactly 20 ticks fire with beat numbers 1..20', () => {
    const m = createMetronome({ bpm: 120 });
    const ticks = [];
    m.on('tick', (beat) => ticks.push(beat));
    const steps = Math.round(10 / DT); // 600 frames
    for (let i = 0; i < steps; i++) stepMetronome(m, DT);
    expect(ticks).toHaveLength(20);
    expect(ticks).toEqual(Array.from({ length: 20 }, (_, i) => i + 1));
  });

  it('arm angle extremes reach 0.5 within 1e-3 and occur midway between ticks', () => {
    const m = createMetronome({ bpm: 120 });
    const tickSteps = [];
    m.on('tick', () => tickSteps.push(m.elapsed));
    const angles = [];
    const steps = Math.round(10 / DT);
    for (let i = 0; i < steps; i++) {
      stepMetronome(m, DT);
      angles.push(m.arm.rotation.z);
    }

    // Extremes reach the amplitude.
    const maxAbs = Math.max(...angles.map(Math.abs));
    expect(Math.abs(maxAbs - 0.5)).toBeLessThan(1e-3);

    // Extremes are located midway between consecutive tick times:
    // collect local maxima of |angle| (one per half-cycle) and compare
    // each against the midpoint of its surrounding ticks.
    const extremeSteps = [];
    for (let i = 1; i < angles.length - 1; i++) {
      const a = Math.abs(angles[i]);
      if (a > Math.abs(angles[i - 1]) && a >= Math.abs(angles[i + 1]) && a > 0.49) {
        extremeSteps.push(i + 1); // 1-based frame index
      }
    }
    // One extreme per half-beat: 2 per beat interval between ticks.
    expect(extremeSteps).toHaveLength(tickSteps.length * 2);

    for (let k = 0; k < tickSteps.length; k++) {
      const before = k === 0 ? 0 : tickSteps[k - 1];
      const after = tickSteps[k];
      const mid = (before + after) / 2;
      for (const s of [extremeSteps[2 * k], extremeSteps[2 * k + 1]]) {
        const t = s * DT;
        expect(Math.abs(t - mid) * m.bpm * 2).toBeLessThan(1e-3); // << half a beat
      }
    }
  });

  it('setBpm mid-run keeps the arm continuous within 1e-6 and doubles subsequent tick spacing', () => {
    const m = createMetronome({ bpm: 120 });
    const tickTimes = [];
    m.on('tick', () => tickTimes.push(m.elapsed));

    // Run 5 seconds, then switch to 60 bpm mid-run.
    for (let i = 0; i < 300; i++) stepMetronome(m, DT);
    const beforeAngle = m.arm.rotation.z;
    const beforeBeats = m.lastBeat;
    setBpm(m, 60);
    const afterAngle = m.arm.rotation.z;

    expect(Math.abs(afterAngle - beforeAngle)).toBeLessThan(1e-6);

    // Beat counter is not reset or duplicated by the tempo change.
    expect(m.lastBeat).toBe(beforeBeats);

    // Run 10 more seconds: at 120 bpm that would be 20 more ticks,
    // at 60 bpm it must be exactly 10 with doubled spacing.
    for (let i = 0; i < 600; i++) stepMetronome(m, DT);
    const postTicks = tickTimes.filter((t) => t > 5);

    expect(postTicks).toHaveLength(10);

    const spacingBefore = [];
    for (let i = 1; i < tickTimes.length && tickTimes[i] <= 5; i++) {
      spacingBefore.push(tickTimes[i] - tickTimes[i - 1]);
    }
    for (const s of spacingBefore) expect(s).toBeCloseTo(0.5, 6);
    const spacingAfter = [];
    for (let i = 1; i < postTicks.length; i++) {
      spacingAfter.push(postTicks[i] - postTicks[i - 1]);
    }
    for (const s of spacingAfter) {
      expect(s).toBeCloseTo(1.0, 6); // doubled from 0.5 s
    }

    // Amplitude unchanged after the switch.
    let maxAbs = 0;
    for (let i = 0; i < 600; i++) {
      stepMetronome(m, DT);
      maxAbs = Math.max(maxAbs, Math.abs(m.arm.rotation.z));
    }
    expect(maxAbs).toBeGreaterThan(0.4999);
  });
});
"})
